MONTHS = {
 'en': 'January February March April May June July August September October November December'.split(),
 'fr': 'janvier février mars avril mai juin juillet août septembre octobre novembre décembre'.split(),
 'ar': 'يناير فبراير مارس أبريل مايو يونيو يوليو أغسطس سبتمبر أكتوبر نوفمبر ديسمبر'.split(),
}
def date(lang, iso):
    y, m, d = iso.split('-')
    if lang == 'zh': return f'{int(y)}年{int(m)}月{int(d)}日'
    if lang == 'fr': return f'{int(d)} {MONTHS["fr"][int(m)-1]} {y}'
    if lang == 'ar': return f'{int(d)} {MONTHS["ar"][int(m)-1]} {y}'
    return f'{int(d)} {MONTHS["en"][int(m)-1]} {y}'

def t(lang, key, **kw):
    v = T[key][LANGS.index(lang)]
    if not v and lang != 'en': v = T[key][0]
    for k, x in kw.items(): v = v.replace('{' + k + '}', str(x))
    return v

def sec(lang, k, i=0): return SECTIONS_T[k][i][LANGS.index(lang)]
